import sys, json
sys.path.insert(0, r"D:\storybound\scripts")
import neatlogs_mcp as m

OUT = r"D:\storybound\evidence\neatlogs\review-2"
F = ["root_span_name", "status", "errored_span_count", "total_tokens", "cost_usd", "duration_ms", "created_at", "session_id"]
W = dict(date_from="2026-10-10T06:00:00Z", date_to="2026-10-11T08:00:00Z")

def search(query, **kw):
    out = m.rpc("tools/call", {"name": "search_traces", "arguments": dict(query=query, fields=F, limit=100, **W, **kw)})
    txt = out["result"]["content"][0]["text"]
    try:
        return json.loads(txt)
    except Exception:
        return {"raw": txt[:500]}

seen = {}
def add(res):
    items = res.get("results") or res.get("traces") or []
    n = 0
    for t in items:
        if t["trace_id"] not in seen:
            seen[t["trace_id"]] = t
            n += 1
    return len(items), n

# probe shape
r = search("error", min_errored_spans=1)
print(list(r.keys()) if isinstance(r, dict) else type(r))
print(json.dumps(r)[:1500])

