"""One reusable MCP session on top of scripts/neatlogs_mcp.py (no key handling here)."""
import sys, json, time
sys.path.insert(0, r"D:\storybound\scripts")
import neatlogs_mcp as m
import httpx

_sid = None
_n = 10

def _open():
    global _sid
    init = m._post({"jsonrpc": "2.0", "id": 0, "method": "initialize", "params": {
        "protocolVersion": "2025-03-26", "capabilities": {}, "clientInfo": {"name": "storybound-evidence", "version": "0.1"}}})
    _sid = init.headers.get("mcp-session-id")
    m._post({"jsonrpc": "2.0", "method": "notifications/initialized"}, _sid)

def _raw_post(payload):
    # like m._post but returns the response instead of exiting on error
    import storybound.config as c
    headers = {"Authorization": f"Bearer {c.env('NEATLOGS_API_KEY')}", "Accept": "application/json, text/event-stream",
               "Content-Type": "application/json"}
    if _sid:
        headers["Mcp-Session-Id"] = _sid
    return httpx.post(m.URL, json=payload, headers=headers, timeout=90)

def call(name, args, tries=6):
    global _sid, _n
    for i in range(tries):
        try:
            if _sid is None:
                r = _raw_post({"jsonrpc": "2.0", "id": 0, "method": "initialize", "params": {
                    "protocolVersion": "2025-03-26", "capabilities": {}, "clientInfo": {"name": "storybound-evidence", "version": "0.1"}}})
                if r.status_code == 429:
                    w = r.json().get("retryAfterSeconds", 60)
                    print("capacity, wait", w, flush=True)
                    time.sleep(min(w + 2, 120))
                    continue
                _sid = r.headers.get("mcp-session-id")
                _raw_post({"jsonrpc": "2.0", "method": "notifications/initialized"})
            _n += 1
            r = _raw_post({"jsonrpc": "2.0", "id": _n, "method": "tools/call", "params": {"name": name, "arguments": args}})
            if r.status_code == 429:
                w = r.json().get("retryAfterSeconds", 60)
                print("429 wait", w, flush=True)
                time.sleep(min(w + 2, 120))
                continue
            if r.status_code >= 400:
                _sid = None
                time.sleep(3)
                continue
            d = m._body(r)
            txt = d["result"]["content"][0]["text"]
            try:
                j = json.loads(txt)
            except Exception:
                return {"_text": txt}
            if isinstance(j, dict) and j.get("errorCode") in ("upstream_unavailable",):
                time.sleep(3)
                continue
            return j
        except Exception as e:
            print("exc", type(e).__name__, flush=True)
            _sid = None
            time.sleep(3)
    return {"_failed": True}

