import sys, json, os, collections
sys.path.insert(0, r"C:\Users\mdhat\AppData\Local\Temp\claude\d--storybound\531bd6f2-4e0c-4a05-a2e1-9f902bd0eeb6\scratchpad")
import nl

POOL = r"D:\storybound\evidence\neatlogs\review-2\trace_pool.json"
OUT = r"D:\storybound\evidence\neatlogs\review-2\trace_detail.json"
pool = json.load(open(POOL))
done = json.load(open(OUT)) if os.path.exists(OUT) else {}

errs = sorted([t for t in pool.values() if t["status"] == "error" and t["workflow_name"] == "create-storybook"], key=lambda t: t["created_at"])
slow = sorted(pool.values(), key=lambda t: -(t["duration_ms"] or 0))[:12]
cost = sorted(pool.values(), key=lambda t: -(t["cost_usd"] or 0))[:12]
vid = [t for t in pool.values() if t["workflow_name"] == "make-video"][:3]
order = []
for grp in (slow, cost, vid, errs):
    for t in grp:
        if t["trace_id"] not in order:
            order.append(t["trace_id"])
print("targets", len(order), flush=True)

def summarize(tid):
    off = 0
    names = collections.Counter(); bad = []; longest = []; head = None; detections = []
    while off is not None:
        d = nl.call("get_trace_context", dict(trace_id=tid, offset=off, include_evaluations=False))
        if "spans" not in d:
            return {"_failed": str(d)[:200]}
        head = {k: d[k] for k in ("status", "latency_ms", "span_count", "llm_calls", "tool_calls", "error_count", "total_tokens", "total_cost", "created_at", "detections")}
        for s in d["spans"]:
            names[s["name"]] += 1
            longest.append((s["duration_ms"] or 0, s["name"], s["type"]))
            if s["status"] != "SUCCESS":
                bad.append({"name": s["name"], "type": s["type"], "status": s["status"], "ms": round(s["duration_ms"] or 0), "out": str(s.get("output_value"))[:350]})
        off = d["next_offset"]
    longest.sort(reverse=True)
    return {"head": head, "names": dict(names.most_common(25)), "bad": bad[:40], "bad_n": len(bad), "longest": longest[:6]}

for i, tid in enumerate(order):
    if tid in done and "_failed" not in done[tid]:
        continue
    done[tid] = summarize(tid)
    json.dump(done, open(OUT, "w"), indent=1, ensure_ascii=False)
    print(i, tid[:12], "bad", done[tid].get("bad_n"), flush=True)
print("DONE")

