import json, re, collections, os
R = r"D:\storybound\evidence\neatlogs\review-2"
det = {}
for f in ("trace_detail.json", "trace_detail_err.json"):
    p = os.path.join(R, f)
    if os.path.exists(p):
        det.update({k: v for k, v in json.load(open(p, encoding="utf-8")).items() if "head" in v})
pool = json.load(open(os.path.join(R, "trace_pool.json")))
print("detailed", len(det))

def cls(b):
    o = b["out"]
    if re.search(r"429|RESOURCE_EXHAUSTED|quota", o, re.I): return "429 quota"
    if re.search(r"504|Deadline", o, re.I): return "504 deadline"
    if re.search(r"499|CANCELLED", o, re.I): return "499 cancelled"
    if re.search(r"ParseError|no JSON|JSONDecode|ValidationError", o): return "parse"
    if re.search(r"missing 'image_prompt'", o): return "page-json-missing-field"
    if re.search(r"503|UNAVAILABLE|overloaded", o, re.I): return "503 unavailable"
    return "other:" + o[:70].replace("\n", " ")

summ = {}
for tid, v in det.items():
    if v["head"]["status"] != "error":
        continue
    c = collections.Counter(cls(b) + " @" + b["name"] for b in v["bad"])
    summ[tid] = c
    print(tid[:12], pool.get(tid, {}).get("created_at", "")[5:16], v["head"]["latency_ms"] // 1000, "s", "err", v["head"]["error_count"], dict(c))
tot = collections.Counter()
for c in summ.values():
    for k in c: tot[k.split(" @")[0]] += 1
print(tot)

