import sys, json, datetime as dt, collections
sys.path.insert(0, r"C:\Users\mdhat\AppData\Local\Temp\claude\d--storybound\531bd6f2-4e0c-4a05-a2e1-9f902bd0eeb6\scratchpad")
import nl
f = lambda x: x.strftime("%Y-%m-%dT%H:%M:%SZ")
hours = [(2026, 10, 10, h) for h in (7, 8, 9, 12, 13, 14)] + [(2026, 10, 11, h) for h in (3, 5, 6, 7)]
KEYS = ["Deadline expired", "429", "RESOURCE_EXHAUSTED", "499", "CANCELLED", "ParseError", "ClientError", "ServerError", "503", "UNAVAILABLE", "ReadTimeout", "ConnectError", "ValidationError"]
res = collections.defaultdict(dict)   # key -> trace_id -> info
for hh in hours:
    t = dt.datetime(*hh); n = t + dt.timedelta(hours=1)
    for k in KEYS:
        d = nl.call("search_traces", dict(query=k, limit=50, min_errored_spans=1, date_from=f(t), date_to=f(n)))
        if "results" not in d:
            print("fail", hh, k, str(d)[:80], flush=True); continue
        for r in d["results"]:
            snips = []
            for m in r.get("matched_spans", []):
                if m.get("span_name") in ("create-storybook",): continue
                snips.append((m.get("span_name"), (m.get("snippet") or "")[:260]))
            res[k][r["trace_id"]] = {"status": r.get("status"), "dur": r.get("duration_ms"), "created": r.get("created_at"), "snips": snips[:3]}
        print(hh[2:], k, d.get("total"), flush=True)
json.dump(res, open(r"D:\storybound\evidence\neatlogs\review-2\error_cause_search.json", "w"), indent=1, ensure_ascii=False)
for k, v in res.items():
    print(k, len(v))

