import sys, json, re
sys.path.insert(0, r"C:\Users\mdhat\AppData\Local\Temp\claude\d--storybound\531bd6f2-4e0c-4a05-a2e1-9f902bd0eeb6\scratchpad")
import nl
crit = json.load(open(r"D:\storybound\evidence\neatlogs\review-2\critical_traces.json"))
out = {}
for tid in sorted(crit, key=lambda t: crit[t]["created_at"]):
    off = 0; lim = 20; hits = []
    while off is not None:
        d = nl.call("get_trace_context", dict(trace_id=tid, offset=off, limit=lim))
        if "spans" not in d:
            if "MCP response limit" in str(d) and lim > 1:
                lim = max(1, lim // 2); continue
            hits.append({"_failed": str(d)[:150]}); break
        for s in d["spans"]:
            o = str(s.get("output_value") or "")
